include { STAR_ALIGN                                                       } from 'nf-core/star/align'
include { BAM_SORT_STATS_SAMTOOLS as BAM_SORT_STATS_SAMTOOLS_GENOME        } from 'nf-core/bam_sort_stats_samtools'
include { BAM_SORT_STATS_SAMTOOLS as BAM_SORT_STATS_SAMTOOLS_TRANSCRIPTOME } from 'nf-core/bam_sort_stats_samtools'


workflow FASTQ_ALIGN_STAR {
    take:
    ch_reads // channel: [ val(meta), [ path(reads) ] ]
    ch_index // channel: [ path(index) ]
    ch_gtf // channel: [ path(gtf) ]
    val_star_ignore_sjdbgtf // boolean: when using pre-built STAR indices do not re-extract and use splice junctions from the GTF file
    ch_fasta_fai // channel: [ val(meta), path(fasta), path(fai) ]
    ch_transcripts_fasta_fai // channel: [ val(meta), path(fasta), path(fai) ]

    main:

    //
    // Map reads with STAR
    //
    STAR_ALIGN(ch_reads, ch_index, ch_gtf, val_star_ignore_sjdbgtf)

    //
    // Sort, index BAM file and run samtools stats, flagstat and idxstats
    //
    BAM_SORT_STATS_SAMTOOLS_GENOME(STAR_ALIGN.out.bam, ch_fasta_fai)

    //
    // Sort, index BAM file and run samtools stats, flagstat and idxstats
    //
    // Only runs when '--quantMode TranscriptomeSAM' is set in args and
    // STAR_ALIGN.out.bam_transcript is populated
    //

    BAM_SORT_STATS_SAMTOOLS_TRANSCRIPTOME(STAR_ALIGN.out.bam_transcript, ch_transcripts_fasta_fai)

    emit:
    orig_bam            = STAR_ALIGN.out.bam // channel: [ val(meta), path(bam)            ]
    log_final           = STAR_ALIGN.out.log_final // channel: [ val(meta), path(log_final)      ]
    log_out             = STAR_ALIGN.out.log_out // channel: [ val(meta), path(log_out)        ]
    log_progress        = STAR_ALIGN.out.log_progress // channel: [ val(meta), path(log_progress)   ]
    bam_sorted          = STAR_ALIGN.out.bam_sorted // channel: [ val(meta), path(bam)            ]
    fastq               = STAR_ALIGN.out.fastq // channel: [ val(meta), path(fastq)          ]
    tab                 = STAR_ALIGN.out.tab // channel: [ val(meta), path(tab)            ]
    orig_bam_transcript = STAR_ALIGN.out.bam_transcript // channel: [ val(meta), path(bam)            ]
    bam                 = BAM_SORT_STATS_SAMTOOLS_GENOME.out.bam // channel: [ val(meta), path(bam) ]
    index               = BAM_SORT_STATS_SAMTOOLS_GENOME.out.index // channel: [ val(meta), path(index) ]
    stats               = BAM_SORT_STATS_SAMTOOLS_GENOME.out.stats // channel: [ val(meta), path(stats) ]
    flagstat            = BAM_SORT_STATS_SAMTOOLS_GENOME.out.flagstat // channel: [ val(meta), path(flagstat) ]
    idxstats            = BAM_SORT_STATS_SAMTOOLS_GENOME.out.idxstats // channel: [ val(meta), path(idxstats) ]
    bam_transcript      = BAM_SORT_STATS_SAMTOOLS_TRANSCRIPTOME.out.bam // channel: [ val(meta), path(bam) ]
    index_transcript    = BAM_SORT_STATS_SAMTOOLS_TRANSCRIPTOME.out.index // channel: [ val(meta), path(index) ]
    stats_transcript    = BAM_SORT_STATS_SAMTOOLS_TRANSCRIPTOME.out.stats // channel: [ val(meta), path(stats) ]
    flagstat_transcript = BAM_SORT_STATS_SAMTOOLS_TRANSCRIPTOME.out.flagstat // channel: [ val(meta), path(flagstat) ]
    idxstats_transcript = BAM_SORT_STATS_SAMTOOLS_TRANSCRIPTOME.out.idxstats // channel: [ val(meta), path(idxstats) ]
}

// IMPORTANT: Add this configuration to your modules.config

process {
    withName: '.*:FASTQ_ALIGN_STAR:BAM_SORT_STATS_SAMTOOLS_GENOME:.*' {
        ext.prefix = { "${meta.id}_genome" }
    }
    withName: '.*:FASTQ_ALIGN_STAR:BAM_SORT_STATS_SAMTOOLS_TRANSCRIPTOME:.*' {
        ext.prefix = { "${meta.id}_transcriptome" }
    }
}

nextflow_workflow {

    name "Test Subworkflow FASTQ_ALIGN_STAR"
    script "../main.nf"
    workflow "FASTQ_ALIGN_STAR"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/fastq_align_star"
    tag "star/align"
    tag "star/genomegenerate"
    tag "rsem/preparereference"
    tag "subworkflows/bam_sort_stats_samtools"
    tag "subworkflows/../bam_sort_stats_samtools"

    setup {
        run("STAR_GENOMEGENERATE") {
            script "../../../../modules/nf-core/star/genomegenerate/main.nf"
            process {
                """
                input[0] = Channel.of([
                    [ id:'test_fasta' ],
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true) ]
                ])
                input[1] = Channel.of([
                    [ id:'test_gtf' ],
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                ])
                """
            }
        }
    }

    test("homo_sapiens - fastq - single_end") {
        config "./nextflow.config"
        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:true ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true) ]
                ])
                input[1] = STAR_GENOMEGENERATE.out.index
                input[2] = Channel.of([
                    [ id:'test_gtf' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                ])
                input[3] = true       // star_ignore_sjdbgtf
                input[4] = Channel.of([
                    [ id:'test_fasta' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ])
                input[5] = Channel.of([[:], [], []])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(
                    bam(workflow.out.bam[0][1]).getReadsMD5(),
                    bam(workflow.out.orig_bam[0][1]).getReadsMD5(),
                    workflow.out.fastq,
                    workflow.out.tab,
                    workflow.out.stats,
                    workflow.out.flagstat,
                    workflow.out.idxstats
                ).match() },
                { assert path(workflow.out.index.get(0).get(1)).exists() },
                { assert path(workflow.out.log_out.get(0).get(1)).exists() },
                { assert path(workflow.out.log_final.get(0).get(1)).exists() },
                { assert path(workflow.out.log_progress.get(0).get(1)).exists() }
            )
        }
    }

    test("homo_sapiens - fastq - paired_end") {
        config "./nextflow.config"

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = STAR_GENOMEGENERATE.out.index
                input[2] = Channel.of([
                    [ id:'test_gtf' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                ])
                input[3] = true       // star_ignore_sjdbgtf
                input[4] = Channel.of([
                    [ id:'test_fasta' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ])
                input[5] = Channel.of([[:], [], []])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(
                    bam(workflow.out.bam[0][1]).getReadsMD5(),
                    bam(workflow.out.orig_bam[0][1]).getReadsMD5(),
                    workflow.out.fastq,
                    workflow.out.tab,
                    workflow.out.stats,
                    workflow.out.flagstat,
                    workflow.out.idxstats
                ).match() },
                { assert path(workflow.out.index.get(0).get(1)).exists() },
                { assert path(workflow.out.log_out.get(0).get(1)).exists() },
                { assert path(workflow.out.log_final.get(0).get(1)).exists() },
                { assert path(workflow.out.log_progress.get(0).get(1)).exists() }
            )
        }
    }

    test("homo_sapiens - fastq - paired_end - with_transcriptome") {
        config "./with_transcripts.config"

        setup {
            run("RSEM_PREPAREREFERENCE") {
                script "../../../../modules/nf-core/rsem/preparereference/main.nf"
                process {
                    """
                    input[0] = channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkifexists: true))
                    input[1] = channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkifexists: true))
                    """
                }
            }
        }
        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = STAR_GENOMEGENERATE.out.index
                input[2] = Channel.of([
                    [ id:'test_gtf' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                ])
                input[3] = true       // star_ignore_sjdbgtf
                input[4] = Channel.of([
                    [ id:'test_fasta' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ])
                input[5] = RSEM_PREPAREREFERENCE.out.transcript_fasta.map{[[:], it, []]}
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(
                    bam(workflow.out.bam[0][1]).getReadsMD5(),
                    bam(workflow.out.orig_bam[0][1]).getReadsMD5(),
                    bam(workflow.out.bam_transcript[0][1]).getReadsMD5(),
                    bam(workflow.out.orig_bam_transcript[0][1]).getReadsMD5(),
                    workflow.out.fastq,
                    workflow.out.tab,
                    workflow.out.stats,
                    workflow.out.flagstat,
                    workflow.out.idxstats,
                    workflow.out.stats_transcript,
                    workflow.out.flagstat_transcript,
                    workflow.out.idxstats_transcript
                ).match() },
                { assert path(workflow.out.index.get(0).get(1)).exists() },
                { assert path(workflow.out.index_transcript.get(0).get(1)).exists() },
                { assert path(workflow.out.log_out.get(0).get(1)).exists() },
                { assert path(workflow.out.log_final.get(0).get(1)).exists() },
                { assert path(workflow.out.log_progress.get(0).get(1)).exists() }
            )
        }
    }

    test("homo_sapiens - fastq - paired_end - transcripts - no_transcriptome") {
        config "./with_transcripts.config"

        when {
            workflow {
                """
                input[0] = Channel.of([
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = STAR_GENOMEGENERATE.out.index
                input[2] = Channel.of([
                    [ id:'test_gtf' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                ])
                input[3] = true       // star_ignore_sjdbgtf
                input[4] = Channel.of([
                    [ id:'test_fasta' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true)
                ])
                input[5] = Channel.of([[:], [], []])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(
                    bam(workflow.out.bam[0][1]).getReadsMD5(),
                    bam(workflow.out.orig_bam[0][1]).getReadsMD5(),
                    workflow.out.fastq,
                    workflow.out.tab,
                    workflow.out.stats,
                    workflow.out.flagstat,
                    workflow.out.idxstats,
                    workflow.out.stats_transcript
                ).match() },
                { assert path(workflow.out.index.get(0).get(1)).exists() },
                { assert path(workflow.out.log_out.get(0).get(1)).exists() },
                { assert path(workflow.out.log_final.get(0).get(1)).exists() },
                { assert path(workflow.out.log_progress.get(0).get(1)).exists() }
            )
        }
    }
}

